def compute(vars):
    denominator = vars["v2"]
    if denominator == 0:
        return None

    ratio = vars["v1"] / denominator
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "deferred_fuel_cost_revisions": vars["v1"],
            "2004_net_revenue": denominator,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
